const listSafeguardingCases = `-- name: ListSafeguardingCases :many
SELECT sc.id, sc.public_reference, sc.category, sc.encrypted_description, sc.incident_date, sc.state_id, sc.lga_id, sc.related_activity, sc.person_involved, sc.is_immediate_danger, sc.is_minor_involved, sc.risk_level, sc.status, sc.is_escalated, sc.escalated_to, sc.escalation_reason, sc.resolution_summary, sc.closed_at, sc.created_at, sc.updated_at, s.name AS state_name, l.name AS lga_name,
       sr.is_anonymous,
       sa.officer_id AS assigned_officer_id,
       u.display_name AS assigned_officer_name
FROM safeguarding_cases sc
LEFT JOIN states s ON s.id = sc.state_id
LEFT JOIN lgas l ON l.id = sc.lga_id
LEFT JOIN safeguarding_reporters sr ON sr.case_id = sc.id
LEFT JOIN safeguarding_assignments sa ON sa.case_id = sc.id AND sa.status = 'active'
LEFT JOIN users u ON u.id = sa.officer_id
WHERE ($3::text IS NULL OR sc.status = $3)
  AND ($4::text IS NULL OR sc.risk_level = $4)
  AND ($5::text IS NULL OR sc.category = $5)
  AND ($6::boolean IS NULL OR sc.is_minor_involved = $6)
  AND ($7::boolean IS NULL OR sc.is_immediate_danger = $7)
ORDER BY
  CASE WHEN sc.is_immediate_danger THEN 0 ELSE 1 END ASC,
  CASE sc.risk_level
    WHEN 'critical' THEN 0
    WHEN 'high' THEN 1
    WHEN 'normal' THEN 2
    ELSE 3
  END ASC,
  sc.created_at DESC
LIMIT $1 OFFSET $2
`

